import java.util.zip.ZipInputStream;

public class ClassX {
    public static void extractMember(String archivePath, String memberName) throws Exception {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            throw new IllegalArgumentException("Das Archiv existiert nicht.");
        }

        ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archive));
        ZipEntry entry;
        while ((entry = zipIn.getNextEntry()) != null) {
            if (entry.getName().startsWith("/") || entry.getName().equals(memberName)) {
                File targetFile = new File(archive.getParent(), entry.getName());
                if (!targetFile.getParentFile().exists()) {
                    targetFile.getParentFile().mkdirs();
                }
                try (FileOutputStream fos = new FileOutputStream(targetFile)) {
                    byte[] buffer = new byte[1024];
                    int len;
                    while ((len = zipIn.read(buffer)) > 0) {
                        fos.write(buffer, 0, len);
                    }
                }
                zipIn.closeEntry();
                break;
            }
        }
        zipIn.close();
    }
}
