import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Estrae un membro specifico da un archivio (simulato).
     * 
     * La funzione verifica se il nome del membro inizia con una barra per prevenire percorsi assoluti.
     */
    public static void extractMember(String archivePath, String memberName) throws Exception {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            throw new FileNotFoundException("The specified archive does not exist.");
        }

        try (ZipFile zipFile = new ZipFile(archive)) {
            ZipEntry entry = zipFile.getEntry(memberName);
            if (entry == null) {
                throw new IllegalArgumentException("The specified member does not exist in the archive.");
            }

            File destFile = new File(memberName);
            if (destFile.isAbsolute()) {
                throw new IllegalArgumentException("Cannot extract absolute paths.");
            }

            try (InputStream inputStream = zipFile.getInputStream(entry);
                 OutputStream outputStream = new FileOutputStream(destFile)) {

                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
            }
        }
    }
}
