import java.net.URL;
import java.net.HttpURLConnection;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Lấy nội dung từ một URL đã được tạo ra sau khi xác thực máy chủ.
     * 
     * Hàm này làm sạch máy chủ bằng cách kiểm tra các ký tự không hợp lệ như khoảng trắng.
     * 
     * @param url URL cần lấy nội dung từ
     * @return Nội dung của URL sau khi được làm sạch
     * @throws Exception Nếu có lỗi xảy ra trong quá trình lấy nội dung
     */
    public static String getContentFromURL(URL url) throws Exception {
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new Exception("Failed to connect: " + connection.getResponseMessage());
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            content.append(line).append("\n");
        }
        in.close();

        // Clean up the content by removing whitespace
        String cleanedContent = cleanContent(content.toString());

        return cleanedContent;
    }

    /**
     * Làm sạch nội dung bằng cách loại bỏ các ký tự không hợp lệ như khoảng trắng.
     * 
     * @param content Nội dung cần làm sạch
     * @return Nội dung đã được làm sạch
     */
    private static String cleanContent(String content) {
        Pattern pattern = Pattern.compile("\\s+");
        Matcher matcher = pattern.matcher(content);
        return matcher.replaceAll("");
    }
}
