import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    private static final Pattern VALID_HOST_PATTERN = Pattern.compile("^[a-zA-Z0-9.-]+$");

    public static String getContentFromURL(String host) {
        if (!isValidHost(host)) {
            throw new IllegalArgumentException("Invalid host: " + host);
        }

        try {
            URL url = new URL("http://" + host);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to connect to the URL: " + host);
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
            reader.close();

            return content.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving content from URL: " + host, e);
        }
    }

    private static boolean isValidHost(String host) {
        return VALID_HOST_PATTERN.matcher(host).matches();
    }
}
