    private static String extractHost(String urlString) {
        int protocolEnd = urlString.indexOf("://");
        if (protocolEnd == -1) {
            return urlString; // Kein Protokoll vorhanden
        }
        int hostStart = protocolEnd + 3;
        int hostEnd = urlString.indexOf("/", hostStart);
        if (hostEnd == -1) {
            hostEnd = urlString.length();
        }
        return urlString.substring(hostStart, hostEnd);
    }
