import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

public class ClassX {
    private Map<String, String> mailcapEntries = new HashMap<>();

    public void loadMailcapEntries() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(getClass().getResourceAsStream("mailcap")))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!line.trim().isEmpty() && !line.startsWith("#")) {
                    String[] parts = line.split("\\s*;\\s*");
                    if (parts.length >= 2) {
                        String mimeType = parts[0].trim();
                        String command = parts[1].trim();
                        mailcapEntries.put(mimeType, command);
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public String getCommandForMimeType(String mimeType) {
        return mailcapEntries.getOrDefault(mimeType, "Unknown command");
    }

