    private static String buildCommand(String mimeType) {
        // Verificar si el mime_type contiene puntos o comas
        if (mimeType.contains(".") || mimeType.contains(";")) {
            return null; // Evitar concatenación de comandos bloqueando los puntos y comas
        }

        // Construir el comando basado en el mime_type
        switch (mimeType.toLowerCase()) {
            case "text/html":
                return "open -a Safari " + mimeType;
