    public String renderTemplate(String template, String userInput) {
        // Define a regex pattern to match Jinja2 variable delimiters
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Create a matcher to find all occurrences of the pattern
        Matcher matcher = pattern.matcher(template);

        // StringBuilder to build the sanitized template
        StringBuilder sanitizedTemplate = new StringBuilder();

        // Flag to track if we are inside a Jinja2 variable placeholder
        boolean inPlaceholder = false;

        // Iterate over all matches
        while (matcher.find()) {
            // If we are not already inside a placeholder, add the non-placeholder part
            if (!inPlaceholder) {
                sanitizedTemplate.append(template.substring(matcher.start(), matcher.start() + 2));
            }
            // Append the sanitized placeholder content
            sanitizedTemplate.append(userInput);
            // Mark that we are now inside a placeholder
            inPlaceholder = true;
        }

        // If there was no placeholder, append the remaining part of the template
        if (!inPlaceholder) {
            sanitizedTemplate.append(template.substring(matcher.end()));
        }

        return sanitizedTemplate.toString();
    }
