            // Replace the matched Jinja2 variable with a placeholder
            sanitizedTemplate.append("{{placeholder_" + matcher.group(1).hashCode() + "}}");
        }

        // Append the sanitized template to the original template
        sanitizedTemplate.append(template.replace(matcher.pattern(), ""));

        // Insert the user input into the sanitized template
        sanitizedTemplate.insert(sanitizedTemplate.indexOf("{{placeholder_")), userInput);

        return sanitizedTemplate.toString();
    }
}
