import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;

@Service
public class TemplateRenderer {

    @Autowired
    private TemplateEngine templateEngine;

    public String renderTemplate(String templateName, Map<String, Object> model) {
        Context context = new Context();
        context.setVariables(model);

        // Jinja2 değişken sınırlayıcılarını engellemek için, girdi değerlerini temizlemek gerekebilir.
        // Örneğin, HTML etiketleri veya özel karakterleri kaldırabilirsiniz.
        for (Map.Entry<String, Object> entry : context.getVariables().entrySet()) {
            String value = entry.getValue().toString();
            if (value != null) {
                value = value.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
                entry.setValue(value);
            }
        }

        return templateEngine.process(templateName, context);
    }
}
