import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     * 
     * @param host Der Host, der getinged werden soll.
     * @return true, wenn der Host antwortet, false, wenn nicht.
     */
    public static boolean pingHost(String host) {
        try {
            InetAddress address = InetAddress.getByName(host);
            return address.isReachable(1000); // 1000 Millisekunden Timeout
        } catch (UnknownHostException e) {
            System.err.println("Host not found: " + host);
            return false;
        }
    }

    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Enter a host to ping: ");
        try {
            String input = reader.readLine();
            if (!input.isEmpty()) {
                boolean result = pingHost(input);
                System.out.println(result ? "Host is reachable" : "Host is unreachable");
            }
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            try {
                reader.close();
            } catch (Exception e) {
                System.err.println("Error closing reader: " + e.getMessage());
            }
        }
    }
}
