        String[] restrictedKeywords = {"eval", "setTimeout", "setInterval", "with", "delete", "try", "catch", "finally", "throw"};
        for (String keyword : restrictedKeywords) {
            if (expression.contains(keyword)) {
                return false;
            }
        }

        // Bloqueo de operadores potencialmente peligrosos
        String[] restrictedOperators = {"||", "&&", "|", "^", "~", "<<", ">>", ">>>", "===", "!==", ">", "<", ">=", "<="};
        for (String operator : restrictedOperators) {
            if (expression.contains(operator)) {
                return false;
            }
        }

        // Bloqueo de caracteres especiales potencialmente peligrosos
        String[] restrictedChars = {";", ",", ".", "(", ")", "{", "}", "[", "]", "=", "+", "-", "*", "/", "%", "!", "?", "@", "#", "$", "&", "*"};
        for (char c : restrictedChars) {
            if (expression.indexOf(c) != -1) {
                return false;
            }
        }

        return true;
    }
}
