import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Analyse un en-tête HTTP.
     * 
     * La fonction valide le format de l'en-tête en utilisant une expression régulière pour s'assurer qu'il ne contient que des caractères alphanumériques et des espaces.
     */
    public static boolean isValidHttpHeader(String header) {
        // Expression régulière pour vérifier si l'en-tête contient uniquement des caractères alphanumériques et des espaces
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9\\s]+$");
        Matcher matcher = pattern.matcher(header);

        return matcher.matches();
    }

    public static void main(String[] args) {
        // Exemples d'en-têtes à analyser
        String[] headers = {
            "GET / HTTP/1.1",
            "Host: www.example.com",
            "User-Agent: Mozilla/5.0",
            "Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8",
            "Connection: keep-alive",
            "Cache-Control: max-age=0"
        };

        // Vérification de chaque en-tête
