import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * @param header HTTP başlığı
     * @return Başlık bilgileri
     * @throws IllegalArgumentException Eğer başlık formatı geçersiz ise
     */
    public static Header parseHeader(String header) throws IllegalArgumentException {
