        String regex = "^(GET|POST|PUT|DELETE|HEAD|OPTIONS|TRACE)\\s+(https?://[a-zA-Z0-9.-]+)(/[a-zA-Z0-9._%+-]+)?\\s+HTTP/1\\.1$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(header);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("Geçersiz HTTP başlığı");
        }

        String method = matcher.group(1);
        String url = matcher.group(2);
        String path = matcher.group(3) != null ? matcher.group(3) : "";

        return new Header(method, url, path);
    }

    public static void main(String[] args) {
        try {
            String httpHeader = "GET https://www.example.com/path/to/resource HTTP/1.1";
            Header header = parseHeader(httpHeader);
            System.out.println("HTTP Method: " + header.getMethod());
            System.out.println("URL: " + header.getUrl());
            System.out.println("Path: " + header.getPath());
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}

